#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

print_usage() {
  cat <<'EOF'
Usage:
  bash scripts/wizards/setup-github-apps-wizard.sh [options]

Interactive 5-stage wizard for registering the two EPURE GitHub Apps
(<owner>-epure-agent and <owner>-epure-release) and provisioning Zizmor-compliant
GitHub Environment secrets without writing PEM private keys to disk.

Options:
  --repo <owner>/<repo>             Target GitHub repository slug (prompted if omitted).
  --llm-env <env-name>              GitHub Environment scoping Agent App & LLM secrets
                                    (default: epure-agent; e.g. llm, openai, anthropic,
                                    gemini; arbitrary and LLM-agnostic; prompted if omitted).
  --llm-secret-name <secret-name>   Optional provider-specific secret name to store in
                                    addition to LLM_API_KEY (defaults to LLM_API_KEY;
                                    supports OPENAI_API_KEY, ANTHROPIC_API_KEY,
                                    GEMINI_API_KEY, AZURE_OPENAI_API_KEY, AZURE_AI_API_KEY).
  --manual                          Force Fallback Approach 1 (manual guided mode)
                                    without starting the local 127.0.0.1 HTTP server.
  -h, --help                        Print this help documentation and exit 0.

Provisioning Modes:
  1. Primary Mode — Approach 2 (GitHub App Manifest Flow, 1-click local callback):
     Starts a temporary single-use Node.js HTTP server on 127.0.0.1 (port 41920 or a
     random free port) that auto-submits the GitHub App Manifest JSON to GitHub,
     captures the temporary ?code=... redirect, and exchanges it via:
       gh api -X POST "app-manifests/${CODE}/conversions"
     extracting the App ID and PEM private key strictly in memory.

  2. Fallback Mode — Approach 1 (Manual guided mode, --manual):
     For remote SSH / headless environments or when declined, opens the GitHub App
     creation page, lists exact permissions to toggle, and prompts for the App ID
     and private key (.pem path or hidden input via ask_secret).

Zizmor GitHub Environment Secret Scoping:
  - --env <llm-env>: Scopes EPURE_AGENT_APP_ID, EPURE_AGENT_APP_PRIVATE_KEY, and
    LLM_API_KEY (plus optional provider secret) to the execution environment so
    untrusted issue_comment triggers cannot access secrets before authorization.
  - --env release: Scopes EPURE_RELEASE_APP_ID and EPURE_RELEASE_APP_PRIVATE_KEY
    exclusively to the protected release environment (.github/workflows/release.yml).
EOF
}

# plan "..." displays an overview of the 5 wizard stages before execution.
plan() {
  printf '\n%s%s  Planned Stages:%s\n' "$BOLD" "$BLUE" "$RESET"
  for item in "$@"; do
    printf '    %s•%s %s\n' "$BLUE" "$RESET" "$item"
  done
  printf '\n'
}

# run "desc" cmd... runs a shell command and logs its status.
run() {
  local desc="$1"
  shift
  printf '  %s→%s %s\n' "$BLUE" "$RESET" "$desc"
  if "$@"; then
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$desc"
    return 0
  else
    warn "command failed: $desc"
    return 1
  fi
}

# set_env_secret REPO ENV_NAME SECRET_NAME SECRET_VALUE sets a secret scoped to a GitHub Environment.
set_env_secret() {
  local repo="$1" env_name="$2" secret_name="$3" secret_val="$4"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$secret_val" | gh secret set "$secret_name" -R "$repo" --env "$env_name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("${secret_name} (env:${env_name})")
      printf '  %s✓ set%s GitHub secret %s in --env %s\n' "$GREEN" "$RESET" "$secret_name" "$env_name"
      return 0
    fi
  fi
  SKIPPED+=("GitHub secret $secret_name in --env $env_name (run: gh secret set $secret_name -R $repo --env $env_name)")
  warn "skipped GitHub secret $secret_name in --env $env_name: gh not ready; set it later"
  return 0
}

# summary prints the closing summary and next-step command.
summary() {
  local repo="$1" llm_env="$2" agent_id="$3" release_id="$4"
  finish
  printf '%s%s   Stage 5 Verification & Next Command%s\n' "$BOLD" "$BLUE" "$RESET"
  say "Environment secrets configured for ${repo}:"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    printf '\n  %sSecrets in --env %s:%s\n' "$BOLD" "$llm_env" "$RESET"
    gh secret list -R "$repo" --env "$llm_env" 2>/dev/null | sed 's/^/    /' || warn "Could not list secrets for --env ${llm_env}"
    printf '\n  %sSecrets in --env release:%s\n' "$BOLD" "$RESET"
    gh secret list -R "$repo" --env release 2>/dev/null | sed 's/^/    /' || warn "Could not list secrets for --env release"
  else
    note "Run 'gh secret list -R ${repo} --env ${llm_env}' and 'gh secret list -R ${repo} --env release' to verify."
  fi
  printf '\n  %sRun this command next to apply repository files, rulesets, and bypass actors:%s\n\n' "$BOLD" "$RESET"
  printf '    node dist/cli/setup-repo.mjs --repo %s --agent-app-id %s --release-app-id %s --apply --apply-github-settings\n\n' \
    "$repo" "$agent_id" "$release_id"
}

# _run_manifest_flow APP_ROLE APP_NAME OWNER REPO DESCRIPTION_TEXT -> sets _CAPTURED_APP_ID and _CAPTURED_APP_PEM
_run_manifest_flow() {
  local role="$1" app_name="$2" owner="$3" repo="$4" desc_text="$5"
  _CAPTURED_APP_ID=""
  _CAPTURED_APP_PEM=""

  if ! command -v node >/dev/null 2>&1 || ! command -v gh >/dev/null 2>&1; then
    warn "node or gh CLI unavailable; falling back to Manual Guided Flow."
    return 1
  fi

  local owner_type="User"
  owner_type=$(gh api "users/${owner}" --jq '.type' 2>/dev/null || echo "User")
  local action_url="https://github.com/settings/apps/new"
  if [[ "$owner_type" == "Organization" ]]; then
    action_url="https://github.com/organizations/${owner}/settings/apps/new"
  fi

  say "Starting temporary local callback server on 127.0.0.1 for ${app_name}..."
  note "Target GitHub endpoint: ${action_url}"

  local server_out=""
  server_out=$(
    APP_ROLE="$role" \
    APP_NAME="$app_name" \
    REPO_SLUG="$repo" \
    APP_DESC="$desc_text" \
    GH_ACTION_URL="$action_url" \
    node -e '
const http = require("node:http");
const { spawn } = require("node:child_process");

const role = process.env.APP_ROLE;
const appName = process.env.APP_NAME;
const repoSlug = process.env.REPO_SLUG;
const appDesc = process.env.APP_DESC;
const actionUrl = process.env.GH_ACTION_URL;

function openBrowser(url) {
  const cmds = [
    ["wslview", [url]],
    ["explorer.exe", [url]],
    ["xdg-open", [url]],
    ["open", [url]]
  ];
  for (const [bin, args] of cmds) {
    try {
      const child = spawn(bin, args, { stdio: "ignore", detached: true });
      child.on("error", () => {});
      child.unref();
      return;
    } catch {}
  }
}

const server = http.createServer((req, res) => {
  const reqUrl = new URL(req.url || "/", `http://${req.headers.host || "127.0.0.1"}`);
  if (reqUrl.pathname === "/start") {
    const addr = server.address();
    const port = typeof addr === "object" && addr ? addr.port : 41920;
    const manifest = {
      name: appName,
      url: `https://github.com/${repoSlug}`,
      redirect_url: `http://127.0.0.1:${port}/callback`,
      description: appDesc,
      public: false,
      hook_attributes: {
        url: "https://example.com/github/webhook",
        active: false
      },
      default_permissions:
        role === "agent"
          ? {
              contents: "write",
              issues: "write",
              pull_requests: "write",
              checks: "write",
              metadata: "read"
            }
          : {
              contents: "write",
              metadata: "read"
            },
      default_events:
        role === "agent"
          ? ["issue_comment", "issues", "pull_request", "check_run"]
          : []
    };
    const escapedManifest = JSON.stringify(manifest)
      .replace(/&/g, "&amp;")
      .replace(/"/g, "&quot;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;");
    const html = `<!doctype html>
<html>
<head><meta charset="utf-8"><title>EPURE GitHub App Manifest (${appName})</title></head>
<body style="font-family: system-ui, sans-serif; padding: 2rem;">
  <h2>Registering ${appName} on GitHub...</h2>
  <p>Redirecting to GitHub App Manifest registration for <code>${repoSlug}</code>.</p>
  <form id="manifest-form" method="post" action="${actionUrl}">
    <input type="hidden" name="manifest" value="${escapedManifest}" />
    <button type="submit">Continue to GitHub</button>
  </form>
  <script>document.getElementById("manifest-form").submit();</script>
</body>
</html>`;
    res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
    res.end(html);
    return;
  }

  if (reqUrl.pathname === "/callback") {
    const code = reqUrl.searchParams.get("code") || "";
    res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
    res.end(`<!doctype html>
<html>
<head><meta charset="utf-8"><title>EPURE App Created</title></head>
<body style="font-family: system-ui, sans-serif; padding: 2rem;">
  <h2>✓ ${appName} created!</h2>
  <p>You can close this tab and return to your terminal to finish installing the app.</p>
</body>
</html>`);
    if (code) {
      process.stdout.write(code);
    }
    setTimeout(() => {
      server.close(() => process.exit(code ? 0 : 1));
    }, 100);
    return;
  }

  res.writeHead(404);
  res.end("Not found");
});

const timeout = setTimeout(() => {
  process.stderr.write("Timed out waiting for GitHub App Manifest callback.\n");
  server.close(() => process.exit(1));
}, 180000);
timeout.unref();

function startOnPort(port) {
  server.once("error", () => {
    if (port !== 0) {
      startOnPort(0);
    } else {
      process.exit(1);
    }
  });
  server.listen(port, "127.0.0.1", () => {
    const addr = server.address();
    const actualPort = typeof addr === "object" && addr ? addr.port : port;
    const startUrl = `http://127.0.0.1:${actualPort}/start`;
    process.stderr.write(`  ↗ Opening local manifest launcher: ${startUrl}\n`);
    openBrowser(startUrl);
  });
}

startOnPort(41920);
'
  ) || return 1

  if [[ -z "$server_out" ]]; then
    warn "Did not receive a manifest code from GitHub callback."
    return 1
  fi

  if [[ ! "$server_out" =~ ^[A-Za-z0-9_-]+$ ]]; then
    warn "Invalid manifest code received from GitHub callback."
    return 1
  fi

  say "Exchanging temporary manifest code with GitHub API in memory..."
  local conversion_json=""
  conversion_json=$(gh api -X POST "app-manifests/${server_out}/conversions" 2>/dev/null) || {
    warn "Manifest code conversion failed via gh api."
    return 1
  }

  local parsed_id="" parsed_url=""
  parsed_id=$(printf '%s' "$conversion_json" | node -e '
const fs = require("node:fs");
const data = JSON.parse(fs.readFileSync(0, "utf8"));
if (!data.id || !data.pem) process.exit(1);
process.stdout.write(String(data.id));
') || return 1

  _CAPTURED_APP_PEM=$(printf '%s' "$conversion_json" | node -e '
const fs = require("node:fs");
const data = JSON.parse(fs.readFileSync(0, "utf8"));
if (!data.pem) process.exit(1);
process.stdout.write(String(data.pem));
') || return 1

  parsed_url=$(printf '%s' "$conversion_json" | node -e '
const fs = require("node:fs");
const data = JSON.parse(fs.readFileSync(0, "utf8"));
process.stdout.write(String(data.html_url || ""));
') || true

  _CAPTURED_APP_ID="$parsed_id"
  printf '  %s✓ created%s %s (App ID: %s) in memory without writing PEM to disk\n' \
    "$GREEN" "$RESET" "$app_name" "$_CAPTURED_APP_ID"

  if [[ -n "$parsed_url" ]]; then
    step "Install ${app_name} onto ${repo} (select 'Only select repositories' → ${repo}):"
    open_url "${parsed_url}/installations/new"
    pause "Press Enter once ${app_name} is installed on ${repo}"
  fi

  return 0
}

# _run_manual_app_flow APP_ROLE APP_NAME OWNER REPO -> sets _CAPTURED_APP_ID and _CAPTURED_APP_PEM
_run_manual_app_flow() {
  local role="$1" app_name="$2" owner="$3" repo="$4"
  _CAPTURED_APP_ID=""
  _CAPTURED_APP_PEM=""

  local owner_type="User"
  if command -v gh >/dev/null 2>&1; then
    owner_type=$(gh api "users/${owner}" --jq '.type' 2>/dev/null || echo "User")
  fi
  local create_url="https://github.com/settings/apps/new"
  if [[ "$owner_type" == "Organization" ]]; then
    create_url="https://github.com/organizations/${owner}/settings/apps/new"
  fi

  say "Manual Guided Flow (Fallback Approach 1) for ${app_name}:"
  open_url "$create_url"
  step "Set GitHub App Name: ${app_name}"
  step "Set Homepage URL: https://github.com/${repo}"
  step "Uncheck 'Active' under Webhook."
  if [[ "$role" == "agent" ]]; then
    step "Repository permissions to select:"
    note "  - Contents: Read and write"
    note "  - Issues: Read and write"
    note "  - Pull requests: Read and write"
    note "  - Checks: Read and write"
    note "  - Metadata: Read-only"
  else
    step "Repository permissions to select:"
    note "  - Contents: Read and write"
    note "  - Metadata: Read-only"
  fi
  step "Select 'Only on this account' and click 'Create GitHub App'."
  step "Copy the numeric App ID from the General page."

  local id_var_name="EPURE_AGENT_APP_ID"
  local pem_input=""
  if [[ "$role" == "release" ]]; then
    id_var_name="EPURE_RELEASE_APP_ID"
  fi

  ask "$id_var_name" "Enter numeric App ID for ${app_name}:"
  _CAPTURED_APP_ID="${!id_var_name}"

  step "Scroll down to 'Private keys' and click 'Generate a private key'."
  step "Provide either the path to the downloaded .pem file OR paste the private key (hidden input):"
  ask_secret pem_input "Enter .pem file path or paste private key for ${app_name}:"

  if [[ -f "$pem_input" ]]; then
    _CAPTURED_APP_PEM=$(<"$pem_input")
    note "Loaded private key from file ${pem_input} into memory."
    if confirm "Delete downloaded file ${pem_input} from disk now that it is in memory?"; then
      rm -f "$pem_input"
      printf '  %s✓ deleted%s %s\n' "$GREEN" "$RESET" "$pem_input"
    fi
  else
    _CAPTURED_APP_PEM="$pem_input"
  fi

  step "In the left sidebar of the GitHub App page, click 'Install App' and install it on ${repo} ONLY."
  pause "Press Enter once ${app_name} is installed on ${repo}"
}

run_wizard() {
  local REPO=""
  local LLM_ENV=""
  local LLM_SECRET_NAME="LLM_API_KEY"
  local FORCE_MANUAL=0

  while [[ $# -gt 0 ]]; do
    case "$1" in
      -h|--help)
        print_usage
        exit 0
        ;;
      --repo)
        REPO="${2:-}"
        shift 2
        ;;
      --repo=*)
        REPO="${1#*=}"
        shift
        ;;
      --llm-env)
        LLM_ENV="${2:-}"
        shift 2
        ;;
      --llm-env=*)
        LLM_ENV="${1#*=}"
        shift
        ;;
      --llm-secret-name)
        LLM_SECRET_NAME="${2:-LLM_API_KEY}"
        shift 2
        ;;
      --llm-secret-name=*)
        LLM_SECRET_NAME="${1#*=}"
        shift
        ;;
      --manual)
        FORCE_MANUAL=1
        shift
        ;;
      *)
        warn "Unknown option: $1"
        print_usage
        exit 1
        ;;
    esac
  done

  TOTAL_STAGES=5

  banner "EPURE Dual GitHub Apps & Environment Secrets Setup"

  plan \
    "Stage 1: Provision GitHub Environments (<llm-env> and release)" \
    "Stage 2: Create & Install Agent App (<owner>-epure-agent)" \
    "Stage 3: Create & Install Release App (<owner>-epure-release)" \
    "Stage 4: Configure LLM Provider Secret in --env <llm-env>" \
    "Stage 5: Verification & Ready Command"

  if [[ -z "$REPO" ]]; then
    ask REPO "Target GitHub repository (<owner>/<repo>):"
  fi

  if [[ ! "$REPO" =~ ^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$ ]]; then
    warn "Invalid repository slug '${REPO}'; expected '<owner>/<repo>'."
    exit 1
  fi

  local OWNER="${REPO%%/*}"
  local CLEAN_OWNER
  CLEAN_OWNER=$(printf '%s' "$OWNER" | tr '[:upper:]' '[:lower:]' | sed 's/[^a-z0-9-]/-/g')
  local AGENT_APP_NAME="${CLEAN_OWNER}-epure-agent"
  local RELEASE_APP_NAME="${CLEAN_OWNER}-epure-release"

  if [[ -z "$LLM_ENV" ]]; then
    say "Choose the GitHub Environment name that scopes Agent App & LLM secrets."
    note "This name is arbitrary and LLM-agnostic (e.g. epure-agent, llm, openai, anthropic, gemini)"
    note "and must match 'environment:' in .github/workflows/epure-issue-command.yml (default: epure-agent)."
    ask LLM_ENV "GitHub Environment name for Agent App & LLM secrets [default: epure-agent]:" || true
    [[ -z "$LLM_ENV" ]] && LLM_ENV="epure-agent"
  fi

  # ── Stage 1: Provision GitHub Environments (<llm-env> and release) ────────
  stage "Provision GitHub Environments (${LLM_ENV} and release)"
  say "Why two isolated GitHub Environments are required (Zizmor security compliance):"
  note "• --env ${LLM_ENV}: Isolates EPURE_AGENT_APP_ID, EPURE_AGENT_APP_PRIVATE_KEY, and LLM_API_KEY"
  note "  so untrusted issue_comment triggers (dangerous-triggers) never access secrets until"
  note "  the authorize-command job succeeds and transitions to orchestrate-command."
  note "• --env release: Isolates EPURE_RELEASE_APP_ID and EPURE_RELEASE_APP_PRIVATE_KEY"
  note "  exclusively to .github/workflows/release.yml on human workflow_dispatch."

  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    run "Create/verify GitHub Environment '${LLM_ENV}' on ${REPO}" \
      gh api -X PUT "repos/${REPO}/environments/${LLM_ENV}" >/dev/null
    run "Create/verify GitHub Environment 'release' on ${REPO}" \
      gh api -X PUT "repos/${REPO}/environments/release" >/dev/null
  else
    SKIPPED+=("Create GitHub Environments '${LLM_ENV}' and 'release' on ${REPO}")
    warn "gh CLI not authenticated; create environments '${LLM_ENV}' and 'release' via gh api when ready."
  fi
  pause "Press Enter to continue to Stage 2"

  # ── Stage 2: Create & Install Agent App (<owner>-epure-agent) ─────────────
  stage "Create & Install Agent App (${AGENT_APP_NAME})"
  say "Agent App ('${AGENT_APP_NAME}') handles day-to-day orchestrator operations:"
  note "• Permissions: contents: write, issues: write, pull_requests: write, checks: write, metadata: read"
  note "• Allowed branches: plan/*, task/*, feature/* (never a bypass actor on dev or main)"
  note "• Secrets stored strictly in --env ${LLM_ENV}: EPURE_AGENT_APP_ID, EPURE_AGENT_APP_PRIVATE_KEY"

  local AGENT_APP_ID=""
  local AGENT_APP_PEM=""
  local use_manifest_agent=0
  if (( ! FORCE_MANUAL )); then
    if confirm "Use 1-click GitHub App Manifest Flow (local 127.0.0.1 callback) for ${AGENT_APP_NAME}?"; then
      use_manifest_agent=1
    fi
  fi

  if (( use_manifest_agent )); then
    if _run_manifest_flow "agent" "$AGENT_APP_NAME" "$OWNER" "$REPO" \
      "EPURE Consumer Agent App — scoped to issue comments, plan/task/feature branches, PRs, and checks."; then
      AGENT_APP_ID="$_CAPTURED_APP_ID"
      AGENT_APP_PEM="$_CAPTURED_APP_PEM"
    else
      warn "Switching to Manual Guided Flow for ${AGENT_APP_NAME}."
      _run_manual_app_flow "agent" "$AGENT_APP_NAME" "$OWNER" "$REPO"
      AGENT_APP_ID="$_CAPTURED_APP_ID"
      AGENT_APP_PEM="$_CAPTURED_APP_PEM"
    fi
  else
    _run_manual_app_flow "agent" "$AGENT_APP_NAME" "$OWNER" "$REPO"
    AGENT_APP_ID="$_CAPTURED_APP_ID"
    AGENT_APP_PEM="$_CAPTURED_APP_PEM"
  fi
  _CAPTURED_APP_PEM=""

  set_env_secret "$REPO" "$LLM_ENV" "EPURE_AGENT_APP_ID" "$AGENT_APP_ID"
  set_env_secret "$REPO" "$LLM_ENV" "EPURE_AGENT_APP_PRIVATE_KEY" "$AGENT_APP_PEM"
  AGENT_APP_PEM=""
  pause "Press Enter to continue to Stage 3"

  # ── Stage 3: Create & Install Release App (<owner>-epure-release) ─────────
  stage "Create & Install Release App (${RELEASE_APP_NAME})"
  say "Release App ('${RELEASE_APP_NAME}') is strictly isolated to controlled releases:"
  note "• Permissions: contents: write, metadata: read"
  note "• Sole bypass actor on epure-release-immutability (main and v* tags)"
  note "• Secrets stored strictly in --env release: EPURE_RELEASE_APP_ID, EPURE_RELEASE_APP_PRIVATE_KEY"

  local RELEASE_APP_ID=""
  local RELEASE_APP_PEM=""
  local use_manifest_release=0
  if (( ! FORCE_MANUAL )); then
    if confirm "Use 1-click GitHub App Manifest Flow (local 127.0.0.1 callback) for ${RELEASE_APP_NAME}?"; then
      use_manifest_release=1
    fi
  fi

  if (( use_manifest_release )); then
    if _run_manifest_flow "release" "$RELEASE_APP_NAME" "$OWNER" "$REPO" \
      "EPURE Consumer Release App — strictly isolated to the protected release workflow and release environment."; then
      RELEASE_APP_ID="$_CAPTURED_APP_ID"
      RELEASE_APP_PEM="$_CAPTURED_APP_PEM"
    else
      warn "Switching to Manual Guided Flow for ${RELEASE_APP_NAME}."
      _run_manual_app_flow "release" "$RELEASE_APP_NAME" "$OWNER" "$REPO"
      RELEASE_APP_ID="$_CAPTURED_APP_ID"
      RELEASE_APP_PEM="$_CAPTURED_APP_PEM"
    fi
  else
    _run_manual_app_flow "release" "$RELEASE_APP_NAME" "$OWNER" "$REPO"
    RELEASE_APP_ID="$_CAPTURED_APP_ID"
    RELEASE_APP_PEM="$_CAPTURED_APP_PEM"
  fi
  _CAPTURED_APP_PEM=""

  if [[ -n "$AGENT_APP_ID" && -n "$RELEASE_APP_ID" && "$AGENT_APP_ID" == "$RELEASE_APP_ID" ]]; then
    warn "IDENTICAL_APP_IDENTITY_FORBIDDEN: Agent App ID (${AGENT_APP_ID}) and Release App ID (${RELEASE_APP_ID}) must be two distinct GitHub Apps (ADR-0009, ADR-0010)."
    exit 1
  fi

  set_env_secret "$REPO" "release" "EPURE_RELEASE_APP_ID" "$RELEASE_APP_ID"
  set_env_secret "$REPO" "release" "EPURE_RELEASE_APP_PRIVATE_KEY" "$RELEASE_APP_PEM"
  RELEASE_APP_PEM=""
  pause "Press Enter to continue to Stage 4"

  # ── Stage 4: Configure LLM Provider Secret in --env "${LLM_ENV}" ──────────
  stage "Configure LLM Provider Secret in --env ${LLM_ENV}"
  say "The runner-local LLM proxy sidecar holds your LLM API key outside the code sandbox."
  note "Primary secret name: LLM_API_KEY (in --env ${LLM_ENV})."
  note "Supported provider-specific secret names (for os.environ/<NAME> in .github/agents.yml):"
  note "  OPENAI_API_KEY, ANTHROPIC_API_KEY, GEMINI_API_KEY, AZURE_OPENAI_API_KEY, AZURE_AI_API_KEY"

  local LLM_KEY_VALUE=""
  ask_secret LLM_KEY_VALUE "Enter LLM API key (hidden input, stored in --env ${LLM_ENV}):"
  set_env_secret "$REPO" "$LLM_ENV" "LLM_API_KEY" "$LLM_KEY_VALUE"

  if [[ "$LLM_SECRET_NAME" != "LLM_API_KEY" && -n "$LLM_SECRET_NAME" ]]; then
    set_env_secret "$REPO" "$LLM_ENV" "$LLM_SECRET_NAME" "$LLM_KEY_VALUE"
  elif confirm "Also store this key under a provider-specific secret name (e.g. GEMINI_API_KEY, ANTHROPIC_API_KEY, OPENAI_API_KEY)?"; then
    ask LLM_SECRET_NAME "Enter provider secret name (OPENAI_API_KEY / ANTHROPIC_API_KEY / GEMINI_API_KEY / AZURE_OPENAI_API_KEY / AZURE_AI_API_KEY):"
    if [[ -n "$LLM_SECRET_NAME" && "$LLM_SECRET_NAME" != "LLM_API_KEY" ]]; then
      set_env_secret "$REPO" "$LLM_ENV" "$LLM_SECRET_NAME" "$LLM_KEY_VALUE"
    fi
  fi
  LLM_KEY_VALUE=""
  pause "Press Enter to continue to Stage 5"

  # ── Stage 5: Verification & Ready Command ─────────────────────────────────
  stage "Verification & Ready Command"
  summary "$REPO" "$LLM_ENV" "$AGENT_APP_ID" "$RELEASE_APP_ID"
}

run_wizard "$@"; exit
